<script setup>
import { computed, ref, watch } from "vue"
import { useRoute } from "vue-router"
import headingIcon from "../assets/images/shop/icon/icon-black.png"
import product01 from "../assets/images/shop/icon/product01.png"
import product02 from "../assets/images/shop/icon/product02.png"
import product03 from "../assets/images/shop/icon/product03.png"
import product04 from "../assets/images/shop/icon/product04.png"
import product05 from "../assets/images/shop/icon/product05.png"
import bannerOne from "../assets/images/shop/homepage/discount01.png"
import bannerTwo from "../assets/images/shop/homepage/discount02.png"
import bannerThree from "../assets/images/shop/homepage/discount03.png"

const galleryAssets = import.meta.glob("../assets/images/shop/all-products/*", { eager: true, import: "default" })
const asset = (file) => Object.entries(galleryAssets).find(([path]) => path.endsWith(`/${file}`))?.[1]
const selectedMain = ref("")
const selectedSub = ref("")
const keyword = ref("")
const currentPage = ref(1)
const selectedProduct = ref(null)
const activeImage = ref(0)
const quantity = ref(1)
const cursor = ref({ x: 0, y: 0, visible: false })
const toast = ref("")
let toastTimer
const bannerIndex = ref(0)
const route = useRoute()
const banners = [[bannerOne, "父親節特定商品88折", "Raise a Glass to the Best Dad."], [bannerTwo, "媽祖平安系列", "A Blessing of Peace"], [bannerThree, "特價優惠", "Hot Sale"]]
const currentBanner = computed(() => banners[bannerIndex.value])
const categories = [
  ["優惠專區", product01, ["父親節88折", "媽祖平安系列", "特價優惠"]],
  ["藝術精品", product02, ["琉璃藝品", "玻璃藝品"]],
  ["生活用品", product03, ["居家生活", "廚房用具"]],
  ["精選品牌", product04, ["HARIO", "LOCK & LOCK", "Pasabahce"]],
  ["體驗活動", product05, ["吹製玻璃", "彩繪玻璃"]],
]
const products = [
  ["優惠專區","父親節88折","御茶香沖泡壺800ml","500","4710981620628","01.jpg"], ["優惠專區","媽祖平安系列","媽祖（水晶座）","3,880","D81300211","02-1.jpeg"], ["優惠專區","特價優惠","黃金萬萬兩","900","F8240000I","03-1.jpg"],
  ["藝術精品","琉璃藝品","台灣祥龍如意","3,000","D81530007","04-1.png"], ["藝術精品","玻璃藝品","福氣彩雞","7,000","OC1030097","05-1.jpg"], ["生活用品","居家生活","風格雙層把手玻璃杯","299","4710069083826","06.jpg"],
  ["生活用品","廚房用具","相思木蓋玻璃儲物罐","229","4710069078822","07-1.jpg"], ["精選品牌","HARIO","V60經典清透咖啡壺","600","4977642022669","08.jpg"], ["精選品牌","LOCK & LOCK","單向排氣密封罐","369","8803733367578","09-1.jpg"],
  ["精選品牌","Pasabahce","390cc 山形杯","320","8693357552456","10.jpg"], ["體驗活動","吹製玻璃","吹製玻璃體驗DIY","680起","OC103005","11-1.png"], ["體驗活動","吹製玻璃","循環再生玻璃吹製體驗","1,199起","OC103005","12.png"],
  ["體驗活動","吹製玻璃","小小玻璃工藝師","799","OC103001H","13-1.png"], ["體驗活動","彩繪玻璃","彩繪玻璃小夜燈DIY","350起","OC103005","14-1.png"],
].map(([parentCategory, category, name, price, code, image], index) => ({ id: index + 1, parentCategory, category, name, price, code, image: asset(image), gallery: galleryFor(index + 1) }))
const filteredProducts = computed(() => products.filter((product) => {
  const matchesMain = !selectedMain.value || product.parentCategory === selectedMain.value
  const matchesSub = !selectedSub.value || product.category === selectedSub.value
  const term = keyword.value.trim().toLowerCase()
  return matchesMain && matchesSub && (!term || `${product.name}${product.category}${product.parentCategory}${product.code}`.toLowerCase().includes(term))
}))
const pageCount = computed(() => Math.max(1, Math.ceil(filteredProducts.value.length / 12)))
const paginatedProducts = computed(() => filteredProducts.value.slice((currentPage.value - 1) * 12, currentPage.value * 12))
const sectionTitle = computed(() => selectedSub.value || selectedMain.value || "所有商品")
function selectMain(name) { selectedMain.value = selectedMain.value === name && !selectedSub.value ? "" : name; selectedSub.value = ""; currentPage.value = 1 }
function selectSub(main, sub) { const same = selectedSub.value === sub; selectedMain.value = same ? "" : main; selectedSub.value = same ? "" : sub; currentPage.value = 1 }
function applyCategoryQuery(category) { const matchedMain = categories.find(([main, , subs]) => main === category || subs.includes(category)); if (!matchedMain) return; selectedMain.value = matchedMain[0]; selectedSub.value = matchedMain[2].includes(category) ? category : ""; currentPage.value = 1 }
watch(() => route.query.category, applyCategoryQuery, { immediate: true })
function galleryFor(id) { const files = { 1:["01.jpg"], 2:["02-1.jpeg","02-2.jpeg","02-3.jpeg","02-4.jpeg"], 3:["03-1.jpg","03-2.jpg","03-3.jpg"], 4:["04-1.png","04-2.png"], 5:["05-1.jpg","05-2.jpg","05-3.jpg","05-4.jpg"], 6:["06.jpg"], 7:["07-1.jpg","07-2.jpg","07-3.jpg"], 8:["08.jpg"], 9:["09-1.jpg","09-2.jpg"], 10:["10.jpg"], 11:["11-1.png","11-2.jpeg","11-3.jpeg","11-4.jpeg"], 12:["12.png"], 13:["13-1.png","13-2.jpg","13-3.jpg","13-4.jpg"], 14:["14-1.png","14-2.jpg","14-3.jpg","14-4.jpg"] }[id] || []; return files.map(asset).filter(Boolean) }
const introductions = [ ["人性化拆裝設計，使產品使用清洗更方便衛生","外觀設計美觀、時尚，裝飾性強","泡出茶水量多","使用食品級材料"], ["採用精細的手法製作，送禮以及店面招財擺飾的好選擇。"], ["適合店面招財擺飾／風水擺設／年節送禮／交換禮物","金元寶有著戴財、聚財的含意，象徵著榮華富貴。元寶是財富的象徵。"], ["祥龍騰躍、如意納福，以東方吉祥文化為靈感打造。"], ["雞常常與吉祥、繁榮、成功以及勇氣等正面象徵相關聯。"], ["輕巧／耐熱／隔熱"], ["廚房系統收納新美學概念","玻璃材質好安心"], ["日本HARIO原裝進口","可微波加熱"], ["自動排出氣體，隔絕外部空氣","瓶身凹槽設計，輕易握住不滑落"], ["珍貴而堅固的無鉛玻璃製成","杯身晶亮剔透，光澤度佳"], ["五歲以上，即可接受高溫體驗挑戰～","一對一的專業教學，帶領您製作專屬自己的玻璃水杯！"], ["走進煉功屋，體驗一場結合ESG永續理念與職人工藝的玻璃吹製旅程。"], ["最火熱！最夯的小小玻璃工藝師體驗營來啦～"], ["彩繪玻璃小夜燈DIY，步驟簡單、老少咸宜。"] ]
const details = [ ["尺寸：14×10×19cm","材質：高朋硅玻璃／PC-1250／SUS-304／環保磁鐵","容量：800ml"], ["尺寸：6×6×9.3±1.5cm","材質：琉璃"], ["尺寸：10×5.5×5.3±0.5cm","材質：水晶玻璃"], ["尺寸：6.5×14.5×7.5cm±1.5cm","材質：琉璃"], ["尺寸：15×19±0.5cm","顏色：紅色、橘色、金色"], ["尺寸：13×9.5×11cm","材質：高硼矽玻璃","容量：380ml"], ["尺寸：9×9×10cm","材質：玻璃／相思木"], ["材質：耐熱玻璃","產地：日本製造"], ["容量：1L","尺寸：11.2×11.2×15.4cm"], ["尺寸：8.5×10cm","產地：土耳其"], ["五歲以上適用"], ["為提供較佳品質之服務，將依預約先後安排。"], ["活動日期前一個禮拜將不接受退款及取消。"], ["顏料自然風乾時間為15–30分鐘。"] ]
products.forEach((product, index) => { product.introduction = introductions[index]; product.details = details[index] })
function openProduct(product) { selectedProduct.value = product; activeImage.value = 0; quantity.value = 1; cursor.value.visible = false }
function closeProduct() { selectedProduct.value = null }
function changeImage(direction) { const length = selectedProduct.value.gallery.length; activeImage.value = (activeImage.value + direction + length) % length }
function moveCursor(event) { cursor.value = { x: event.clientX, y: event.clientY, visible: true } }
function addToCart(product, count = 1) { toast.value = `${product.name} × ${count} 已加入購物車`; window.clearTimeout(toastTimer); toastTimer = window.setTimeout(() => { toast.value = "" }, 2200) }
</script>

<template>
  <main class="shop-products-page">
    <section class="products-hero" @pointermove="moveCursor" @pointerenter="moveCursor" @pointerleave="cursor.visible = false">
      <img :src="currentBanner[0]" :alt="currentBanner[1]">
      <div class="hero-shade"></div><div class="hero-copy"><h1>{{ currentBanner[1] }}</h1><p>{{ currentBanner[2] }}</p></div>
      <div class="hero-dots" @pointerenter="cursor.visible = false"><button v-for="(_, index) in banners" :key="index" :class="{ active: bannerIndex === index }" @click="bannerIndex = index"></button></div>
    </section>
    <div class="promotion-strip">全館滿 $500 享「貨到付款」，滿 $2,000 享「免運」</div>
    <section class="catalog">
      <div class="catalog-wrap">
        <div class="category-grid">
          <article v-for="[name, icon, subcategories] in categories" :key="name" class="category-card">
            <button class="category-main" :class="{ active: selectedMain === name && !selectedSub }" @click="selectMain(name)"><img :src="icon" alt=""><span>{{ name }}</span></button>
            <div class="subcategory-list"><button v-if="name === '優惠專區'" :class="{ active: !selectedMain && !selectedSub }" @click="selectedMain = ''; selectedSub = ''; currentPage = 1">所有商品</button><button v-for="sub in subcategories" :key="sub" :class="{ active: selectedSub === sub }" @click="selectSub(name, sub)">{{ sub }}</button></div>
          </article>
        </div>
      </div>
    </section>
    <section class="products-section">
      <div class="catalog-wrap">
        <div class="products-head">
          <h2><img :src="headingIcon" alt="">{{ sectionTitle }}</h2>
          <label class="search-box"><span class="sr-only">搜尋商品</span><input v-model="keyword" type="search" placeholder="搜尋商品名稱、分類或商品編號……"><i></i></label>
        </div>
        <div class="product-grid">
          <article v-for="product in paginatedProducts" :key="product.id" class="product-card">
            <button class="product-image" @click="openProduct(product)" @pointermove="moveCursor" @pointerenter="moveCursor" @pointerleave="cursor.visible = false"><img :src="product.image" :alt="product.name"></button>
            <div class="product-meta"><p>{{ product.category }}</p><button class="product-name" @click="openProduct(product)">{{ product.name }}</button><div><strong>NT$ {{ product.price }}</strong><button aria-label="加入購物車" @click="addToCart(product)">＋</button></div></div>
          </article>
        </div>
        <nav v-if="pageCount > 1" class="pagination" aria-label="商品分頁"><button class="arrow" :disabled="currentPage === 1" @click="currentPage--">‹</button><button v-for="page in pageCount" :key="page" :class="{ active: currentPage === page }" @click="currentPage = page">{{ page }}</button><button class="arrow" :disabled="currentPage === pageCount" @click="currentPage++">›</button></nav>
        <p v-if="!filteredProducts.length" class="empty">找不到符合條件的商品</p>
      </div>
    </section>
    <div class="glass-cursor" :class="{ visible: cursor.visible }" :style="{ left: `${cursor.x}px`, top: `${cursor.y}px` }">MORE ↗</div><Transition name="toast"><p v-if="toast" class="cart-toast">{{ toast }}</p></Transition>
    <Teleport to="body"><Transition name="modal"><div v-if="selectedProduct" class="modal-backdrop" @click.self="closeProduct"><article class="product-modal"><button class="modal-close" aria-label="關閉" @click="closeProduct">×</button><section class="modal-gallery"><div class="modal-image"><button v-if="selectedProduct.gallery.length > 1" class="gallery-arrow prev" @click="changeImage(-1)">‹</button><img :src="selectedProduct.gallery[activeImage]" :alt="selectedProduct.name"><button v-if="selectedProduct.gallery.length > 1" class="gallery-arrow next" @click="changeImage(1)">›</button></div><div class="thumbnails"><button v-for="(image, index) in selectedProduct.gallery" :key="image" :class="{ active: activeImage === index }" @click="activeImage = index"><img :src="image" alt=""></button></div></section><section class="modal-copy"><p class="modal-category">{{ selectedProduct.category }}</p><h2>{{ selectedProduct.name }}</h2><p class="modal-code">商品編號：{{ selectedProduct.code }}</p><h3>商品介紹</h3><ul><li v-for="item in selectedProduct.introduction" :key="item">{{ item }}</li></ul><h3>產品規格</h3><ul><li v-for="item in selectedProduct.details" :key="item">{{ item }}</li></ul><footer><strong>NT$ {{ selectedProduct.price }}</strong><div class="quantity"><button @click="quantity = Math.max(1, quantity - 1)">−</button><span>{{ quantity }}</span><button @click="quantity++">＋</button></div><button class="cart-button" @click="addToCart(selectedProduct, quantity)">🛒　加入購物車</button></footer></section></article></div></Transition></Teleport>
  </main>
</template>

